import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import response from '../train_details.json'

function TrainDetails() {
  const { train_number } = useParams();
  const [route, setRoute] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchTrainRoute = async () => {
      try {
        // const response = await fetch(`https://rappid.in/apis/train.php?train_no=${train_number}`);
        // if (!response.ok) {
        //   throw new Error('Network response was not ok');
        // }
        const {success}=response
        if (success) {
          setRoute(response["data"]);
        } else {
          throw new Error('Failed to fetch train data');
        }
        setLoading(false);
      } catch (error) {
        setError(error);
        setLoading(false);
      }
    };

    fetchTrainRoute();
  }, []);

  if (loading) {
    return <p>Loading...</p>;
  }

  if (error) {
    return <p>Error: {error.message}</p>;
  }
  return (
    <div style={{backgroundColor: 'grey'}}>
      {route.map(station_info => (
        <Station key={station_info.id} props={station_info} />
      ))}
    </div>
  );
}

export default TrainDetails;
